// frontend/src/components/InsertTradeForm.jsx

import React, { useState } from "react";
import { insertTrade } from "../services/api";

export default function InsertTradeForm({ onInserted }) {
  const [form, setForm]       = useState({ stock_id: 1, seller_id: "", buyer_id: "", price: "", quantity: "" });
  const [status, setStatus]   = useState(null);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setStatus(null);
    try {
      const result = await insertTrade({
        stock_id:  parseInt(form.stock_id),
        seller_id: parseInt(form.seller_id),
        buyer_id:  parseInt(form.buyer_id),
        price:     parseFloat(form.price),
        quantity:  parseInt(form.quantity)
      });
      setStatus({ type: "success", msg: `✅ Trade #${result.trade_id} inserted! Watch for fraud alert...` });
      onInserted?.();
    } catch (err) {
      setStatus({ type: "error", msg: "❌ Insert failed" });
    }
    setLoading(false);
  };

  // Quick inject fraud button — uses ring trader IDs
  const injectFraud = () => {
    setForm({ stock_id: 1, seller_id: "1", buyer_id: "2", price: "499.99", quantity: "100" });
  };

  const fields = [
    { name: "seller_id", label: "Seller ID",  placeholder: "e.g. 1" },
    { name: "buyer_id",  label: "Buyer ID",   placeholder: "e.g. 2" },
    { name: "stock_id",  label: "Stock ID",   placeholder: "1–30"   },
    { name: "price",     label: "Price ($)",  placeholder: "e.g. 499.99" },
    { name: "quantity",  label: "Quantity",   placeholder: "e.g. 100" },
  ];

  return (
    <div style={{ background: "#1e293b", padding: "20px", borderRadius: "12px" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "16px" }}>
        <h3 style={{ margin: 0 }}>➕ Insert Live Trade</h3>
        <button onClick={injectFraud} style={{
          background: "#ef4444", color: "#fff", border: "none",
          padding: "6px 14px", borderRadius: "6px", cursor: "pointer", fontSize: "0.85rem"
        }}>
          🔴 Inject Fraud Trade
        </button>
      </div>

      <form onSubmit={handleSubmit}>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(160px,1fr))", gap: "12px", marginBottom: "16px" }}>
          {fields.map((f) => (
            <div key={f.name}>
              <label style={{ fontSize: "0.8rem", color: "#94a3b8", display: "block", marginBottom: "4px" }}>
                {f.label}
              </label>
              <input
                name={f.name}
                value={form[f.name]}
                onChange={handleChange}
                placeholder={f.placeholder}
                required
                style={{
                  width: "100%", padding: "8px", borderRadius: "6px",
                  background: "#0f172a", border: "1px solid #334155",
                  color: "#f1f5f9", boxSizing: "border-box"
                }}
              />
            </div>
          ))}
        </div>
        <button type="submit" disabled={loading} style={{
          background: "#3b82f6", color: "#fff", border: "none",
          padding: "10px 24px", borderRadius: "8px", cursor: "pointer",
          fontWeight: "bold", opacity: loading ? 0.6 : 1
        }}>
          {loading ? "Inserting..." : "Submit Trade"}
        </button>
      </form>

      {status && (
        <div style={{
          marginTop: "12px", padding: "10px", borderRadius: "8px",
          background: status.type === "success" ? "rgba(34,197,94,0.1)" : "rgba(239,68,68,0.1)",
          color: status.type === "success" ? "#22c55e" : "#ef4444"
        }}>
          {status.msg}
        </div>
      )}
    </div>
  );
}
